<?php $statusLabels=['pending'=>'Pending','accepted'=>'Accepted','rejected'=>'Rejected','expired'=>'Expired']; $isEdit=$section==='estimates-edit'; ?>
<div class="customer-modal-backdrop estimate-form-backdrop" role="presentation"><section class="estimate-side-panel" role="dialog" aria-modal="true" aria-labelledby="estimate-form-title"><div class="estimate-panel-header"><div><h2 id="estimate-form-title"><?= $isEdit?'Edit Estimate':'Create Estimate' ?></h2><span><?= $isEdit?'Update estimate details':'Create a service estimate for a customer' ?></span></div><a href="index.php?page=admin&amp;section=estimates" aria-label="Close">&times;</a></div><div class="estimate-panel-body"><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" id="estimate-form" action="index.php?page=admin&amp;section=<?= e($section) ?>&amp;id=<?= (int)$id ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><section class="estimate-form-section"><h3>Customer &amp; Vehicle</h3><div class="row g-3"><div class="col-7"><label class="form-label">Customer *</label><select class="form-select" name="customer_id" id="estimate-customer" required><option value="">Select customer</option><?php foreach($customers as $customer): ?><option value="<?= (int)$customer['id'] ?>" <?= $input['customer_id']===(int)$customer['id']?'selected':'' ?>><?= e($customer['name']) ?></option><?php endforeach; ?></select></div><div class="col-5"><label class="form-label">Vehicle *</label><select class="form-select" name="vehicle_id" id="estimate-vehicle"><option value="0">Select vehicle</option><?php foreach($vehicles as $vehicle): ?><option data-customer-id="<?= (int)$vehicle['customer_id'] ?>" value="<?= (int)$vehicle['id'] ?>" <?= $input['vehicle_id']===(int)$vehicle['id']?'selected':'' ?>><?= e($vehicle['vehicle_number']) ?></option><?php endforeach; ?></select></div><div class="col-4"><label class="form-label">Mileage (KM)</label><input class="form-control" type="number" step="0.01" name="mileage" value="<?= e($input['mileage']) ?>" placeholder="Enter mileage"></div><div class="col-4"><label class="form-label">Engine No.</label><input class="form-control" name="engine_number" value="<?= e($input['engine_number']) ?>" placeholder="Engine no."></div><div class="col-4"><label class="form-label">Chassis No.</label><input class="form-control" name="chassis_number" value="<?= e($input['chassis_number']) ?>" placeholder="Chassis no."></div></div></section><section class="estimate-form-section"><h3>Estimate Details</h3><div class="row g-3"><div class="col-6"><label class="form-label">Estimate Date *</label><input class="form-control" type="date" name="estimate_date" value="<?= e($input['estimate_date']) ?>" required></div><div class="col-6"><label class="form-label">Valid Until *</label><input class="form-control" type="date" name="valid_until" value="<?= e($input['valid_until']) ?>" required></div><div class="col-8"><label class="form-label">Service Type / Issue *</label><input class="form-control" name="service_type" value="<?= e($input['service_type']) ?>" placeholder="Select or enter service type" required></div><div class="col-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach($statusLabels as $value=>$label): ?><option value="<?= e($value) ?>" <?= $input['status']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2" maxlength="250" placeholder="Add any notes about the estimate..."><?= e($input['notes']) ?></textarea></div></div></section><section class="estimate-form-section"><div class="estimate-items-heading"><h3>Estimate Items</h3><button type="button" class="btn btn-outline-danger btn-sm" id="add-estimate-item">+ Add Item</button></div><div id="estimate-items"><?php foreach($input['items'] as $index=>$item): ?><div class="estimate-item-row"><input class="form-control" name="items[<?= $index ?>][name]" value="<?= e($item['name']) ?>" placeholder="Item / Service" required><input class="form-control estimate-qty" type="number" min="0.01" step="0.01" name="items[<?= $index ?>][quantity]" value="<?= e($item['quantity']) ?>"><input class="form-control estimate-price" type="number" min="0" step="0.01" name="items[<?= $index ?>][unit_price]" value="<?= e($item['unit_price']) ?>"><output class="estimate-line-amount">0.00</output><button type="button" class="estimate-remove-item" title="Remove item">&times;</button></div><?php endforeach; ?></div></section><section class="estimate-total-box"><div><span>Sub Total</span><strong id="estimate-subtotal">Rs. 0.00</strong></div><div><label>Discount <input class="form-control" id="estimate-discount" type="number" min="0" step="0.01" name="discount" value="<?= e($input['discount']) ?>"></label><strong id="estimate-discount-display">Rs. 0.00</strong></div><div><label>VAT (%) <input class="form-control" id="estimate-vat-rate" type="number" min="0" step="0.01" name="vat_rate" value="<?= e($input['vat_rate']) ?>"></label><strong id="estimate-vat-display">Rs. 0.00</strong></div><div class="estimate-grand-total"><span>Total Amount</span><strong id="estimate-total">Rs. 0.00</strong></div></section><div class="estimate-form-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=estimates">Cancel</a><button class="btn btn-danger" type="submit">Save Estimate</button></div></form></div></section></div>
<script>
document.addEventListener('DOMContentLoaded',function(){const form=document.getElementById('estimate-form'),items=document.getElementById('estimate-items'),add=document.getElementById('add-estimate-item'),customer=document.getElementById('estimate-customer'),vehicle=document.getElementById('estimate-vehicle');let next=items.querySelectorAll('.estimate-item-row').length;function filterVehicles(){Array.from(vehicle.options).forEach(function(o){if(!o.dataset.customerId)return;o.hidden=!!customer.value&&o.dataset.customerId!==customer.value;if(o.hidden&&o.selected)vehicle.value='0';});}function totals(){let sub=0;items.querySelectorAll('.estimate-item-row').forEach(function(row){const q=parseFloat(row.querySelector('.estimate-qty').value)||0,p=parseFloat(row.querySelector('.estimate-price').value)||0,a=q*p;row.querySelector('.estimate-line-amount').value=a.toFixed(2);row.querySelector('.estimate-line-amount').textContent=a.toFixed(2);sub+=a;});const discount=Math.min(parseFloat(document.getElementById('estimate-discount').value)||0,sub),rate=parseFloat(document.getElementById('estimate-vat-rate').value)||0,vat=(sub-discount)*rate/100;document.getElementById('estimate-subtotal').textContent='Rs. '+sub.toFixed(2);document.getElementById('estimate-discount-display').textContent='Rs. '+discount.toFixed(2);document.getElementById('estimate-vat-display').textContent='Rs. '+vat.toFixed(2);document.getElementById('estimate-total').textContent='Rs. '+(sub-discount+vat).toFixed(2);}function bind(row){row.querySelectorAll('input').forEach(function(i){i.addEventListener('input',totals);});row.querySelector('.estimate-remove-item').addEventListener('click',function(){row.remove();totals();});}add.addEventListener('click',function(){const row=document.createElement('div');row.className='estimate-item-row';row.innerHTML='<input class="form-control" name="items['+next+'][name]" placeholder="Item / Service" required><input class="form-control estimate-qty" type="number" min="0.01" step="0.01" name="items['+next+'][quantity]" value="1"><input class="form-control estimate-price" type="number" min="0" step="0.01" name="items['+next+'][unit_price]" value="0"><output class="estimate-line-amount">0.00</output><button type="button" class="estimate-remove-item">&times;</button>';items.appendChild(row);bind(row);next++;});items.querySelectorAll('.estimate-item-row').forEach(bind);document.getElementById('estimate-discount').addEventListener('input',totals);document.getElementById('estimate-vat-rate').addEventListener('input',totals);customer.addEventListener('change',filterVehicles);filterVehicles();totals();});
</script>
